// Helper function to invert a 4x4 matrix and compute determinant
bool invert4x4(const Eigen::Matrix4d& H, Eigen::Matrix4d& H_inv, double& det) {
    det = H.determinant();
    if (std::abs(det) < 1e-15) {
        return false; // Singular matrix
    }
