std::vector<Eigen::Matrix<double,6,3>> computeC(const Eigen::Matrix4d& H_inv) {
    std::vector<Eigen::Matrix<double,6,3>> C(4);

    for (int i = 0; i < 4; ++i) {
        C[i] = Eigen::Matrix<double,6,3>::Zero();
        // Gradient of shape function i: [dN_i/dx, dN_i/dy, dN_i/dz]
