        double gy = H_inv(i,2);
        double gz = H_inv(i,3);

        // Standard 3D linear tetrahedron B-matrix (6x3) for node i:
        // Row 0: [gx, 0,   0  ]
        // Row 1: [0,  gy,  0  ]
        // Row 2: [0,  0,   gz ]
        // Row 3: [gy, gx,  0  ]  // γ_xy = ∂u/∂y + ∂v/∂x
        // Row 4: [0,  gz,  gy ]  // γ_yz = ∂v/∂z + ∂w/∂y
        // Row 5: [gz, 0,   gx ]  // γ_xz = ∂u/∂z + ∂w/∂x
        C[i](0,0) = gx;
        C[i](1,1) = gy;
        C[i](2,2) = gz;
        C[i](3,0) = gy; C[i](3,1) = gx;
        C[i](4,1) = gz; C[i](4,2) = gy;
        C[i](5,0) = gz; C[i](5,2) = gx;
    }

    return C;
